import{_ as r,l as t,o,c as i,v as a,p as n,x as d,d as l,i as s,S as E}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"模块与头文件","description":"","frontmatter":{"title":"模块与头文件","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/module-header.md","filePath":"cs/module-header.md","lastUpdated":1789023840000}'),p={name:"cs/module-header.md"};function h(B,e,f,m,A,u){const c=t("Mermaid");return o(),i("div",null,[e[1]||(e[1]=a('<h1 id="模块与头文件" tabindex="-1">模块与头文件 <a class="header-anchor" href="#模块与头文件" aria-label="Permalink to &quot;模块与头文件&quot;">​</a></h1><div class="epigraph"><p>每个源文件是一次独立翻译；头文件把声明复制进多个编译单元，链接阶段再把同名定义收成一份。</p><footer>—— 据 ISO/IEC 9899；Kernighan &amp; Ritchie, The C Programming Language, 2nd ed. 整理</footer></div><p>上一课<a href="/cs/fn-abstraction-boundary">函数作为抽象边界</a>把契约钉在函数上。本课不重讲前置条件，也不从包管理器另起。缺口是：分别编译已经在第一课出现，<strong>调用方如何在看不见函数体时仍拿到正确的声明</strong>。头文件是契约的可包含文本，不是「把代码放在 <code>.h</code> 里」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一个翻译单元看不到另一个 <code>.c</code> 里的定义，只能看见自己包含过的声明。若声明与定义不一致，编译器在本单元内无法发现，链接或运行时才爆。缺口因此不是 <code>#include</code> 的语法，而是<strong>声明与定义的分工</strong>：头文件放共享声明（函数原型、结构体类型、<code>extern</code> 变量），定义只出现在一个 <code>.c</code> 里。第一课的符号解析在这里变成日常纪律。</p><p>把函数定义写进头文件再被多处包含，会得到重复的强符号。内联函数与 <code>static</code> 定义有特殊规则，本课只点名：默认模型是「头文件无定义」。类型必须共享：结构体布局若在两个单元里声明得不同，就变成静默 ABI 破裂——上一课的布局契约跨过了文件边界。</p><h3 id="头文件不是模块系统" tabindex="-1">头文件不是模块系统 <a class="header-anchor" href="#头文件不是模块系统" aria-label="Permalink to &quot;头文件不是模块系统&quot;">​</a></h3><p>C 的 <code>#include</code> 是文本插入，由<a href="/cs/preprocessor-preview">预处理器</a>在更后课展开。它不提供命名空间、不导出可见性图、不防止循环依赖，只靠包含守卫避免同一文件在一次翻译里插两次。把 <code>.h</code> 理解成 Java 的 <code>package</code> 或后来的 C++ 模块，会期待编译器去解依赖图；本栏的构建系统课才会补「谁依赖谁」。</p><p><span class="marginnote">ISO C 的链接：外部链接的标识符在整个程序里指同一对象或函数。K&amp;R 把程序拆成多文件，用头文件共享声明。本课不把 GNU 的可见性属性当主干。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>惯例：<code>foo.h</code> 声明 <code>foo</code> 的接口；<code>foo.c</code> 包含 <code>foo.h</code> 并给出定义——这让编译器核对原型是否自洽。调用方只包含 <code>foo.h</code>。全局变量用 <code>extern</code> 声明、单一 <code>.c</code> 定义。结构体若只通过指针使用，可以不完整类型：头文件里只写 <code>typedef struct Foo Foo;</code>，完整布局藏在 <code>.c</code> 里。这是 C 里封装的主要手段，后课不变量会用到。</p>',11)),(o(),n(E,null,{default:d(()=>[s(c,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E5%A4%B4%E6%96%87%E4%BB%B6%EF%BC%9A%E5%A3%B0%E6%98%8E%E4%B8%8E%E7%B1%BB%E5%9E%8B%22%5D%20--%3E%20A%5B%22%E7%BC%96%E8%AF%91%E5%8D%95%E5%85%83%20A%22%5D%0A%20%20H%20--%3E%20B%5B%22%E7%BC%96%E8%AF%91%E5%8D%95%E5%85%83%20B%22%5D%0A%20%20C1%5B%22foo.c%EF%BC%9A%E5%94%AF%E4%B8%80%E5%AE%9A%E4%B9%89%22%5D%20--%3E%20OBJ1%5B%22%E7%9B%AE%E6%A0%87%E6%96%87%E4%BB%B6%22%5D%0A%20%20A%20--%3E%20OBJ2%5B%22%E5%8F%A6%E4%B8%80%E7%9B%AE%E6%A0%87%E6%96%87%E4%BB%B6%22%5D%0A%20%20OBJ1%20--%3E%20LINK%5B%22%E9%93%BE%E6%8E%A5%E6%88%90%E4%B8%80%E4%BB%BD%E7%AC%A6%E5%8F%B7%22%5D%0A%20%20OBJ2%20--%3E%20LINK%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>包含守卫（<code>#ifndef</code>/<code>#define</code>/<code>#endif</code> 或 <code>#pragma once</code>）保证一次翻译内类型只定义一次。循环包含要用不完整类型或把共享类型抽到第三份头文件，而不是靠预处理器「聪明」。</p><p>公开头文件应最小：只放调用方需要的类型与函数。内部函数保持 <code>static</code> 或留在不安装的头里。这样版本历史里的公开差才短，审查才读得完。循环依赖常用不完整类型拆开：A 只持有 <code>B *</code>，B 的完整定义在别处。这与封装课将用的手法相同，本课先为了让编译顺序成立。预处理器稍后会解释守卫如何阻止同一头文件在一次翻译里插两次；守卫不解决两个头互相包含时的类型不完整问题，那要靠设计。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分别编译能缩放程序，是因为每个单元只依赖头文件里的文本契约。代价是契约必须稳定：改结构体字段、改函数原型，所有包含者都要重编译——这是后课构建系统要跟踪的边。链接器只看见符号名，看不见 C 类型，所以类型错误跨单元时不会在链接期以类型形式出现。头文件的纪律就是在补链接器看不见的那一层。</p><p>构建系统稍后会把「谁包含了这份头文件」画成边：改布局则边的下游全部过期。若把定义藏进头文件并用 <code>static</code> 让每份翻译单元各有一份，符号不冲突，但程序里会出现多份独立静态状态，与「一个模块一份表」相反。内联与 <code>static inline</code> 是受控例外，必须保证所有包含者看见同一语义。链接器的弱符号可以合并，不应当用来掩盖「定义放错文件」。后课错误码会把失败语义也放进这份共享声明里，否则各单元会对失败有不同想象。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写预处理器宏的全部陷阱，不讲动态库的符号版本。下一课<a href="/cs/error-code-failure">错误码与失败</a>把契约里「失败怎么办」补上。后课默认：声明进头文件、定义只一份；跨单元共享的是声明文本；布局不一致是静默错误。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>翻译单元独立编译；头文件复制声明，链接合并定义。</li><li>定义进一个 <code>.c</code>；重复包含定义会造成重复符号。</li><li>不完整类型让布局藏在实现文件里。</li><li>下一课在接口上表达失败。</li><li>出处：ISO C 链接；K&amp;R 多文件程序。</li></ul>',9))])}const b=r(p,[["render",h]]);export{C as __pageData,b as default};
